// OTOMATİK ÜRETİLİR (_tasarim/araclar/gom.py) — elle düzenleme. GPT G5 tek parça boyalı sahneler (1600x738) ve Mini Dizi kapakları (960x540)
const D = {
"koru-sancak":"",
"koru-ocak":"",
"maden":"",
"dipsiz-kuyu":"",
"yeralti-ocagi":"",
"balik-tut":"",
"kristal-nobeti":"",
"dunya-baskini":"",
"minidizi-01":"",
"minidizi-02":"",
"minidizi-03":"",
"minidizi-04":"",
"minidizi-05":"",
"minidizi-06":"",
"minidizi-07":"",
"minidizi-08":"",
"minidizi-09":"",
"minidizi-10":""
};
const U = {};
export const KEYS = Object.keys(D);
export const has = k => !!D[k];
export const url = k => { if (U[k]) return U[k]; const s = D[k]; if (!s) return null;
  try { const b = atob(s), a = new Uint8Array(b.length); for (let i = 0; i < b.length; i++) a[i] = b.charCodeAt(i); return (U[k] = URL.createObjectURL(new Blob([a], { type: 'image/webp' }))); }
  catch { return (U[k] = 'data:image/webp;base64,' + s); } };
